import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`market-research`,heroTitle:`Understand any market in minutes`,heroSubtitle:`Perplexity Computer researches the entire market, builds industry models, and generates your full report package — automatically.`,inputUrlCta:`Research market`,inputUrlPlaceholder:`e.g. electric vehicle charging`,inputUrlPrefill:`Research the {url} market end-to-end. Analyze the competitive landscape, key players, and market trends. Build TAM/SAM/SOM models with growth projections and unit economics. Generate an executive report and presentation with full market analysis. Create a strategic playbook covering positioning, pricing, and go-to-market strategy.`,heroOverlaySteps:[`Scanning 100+ sources on competitors, trends, and key players`,`Building TAM/SAM/SOM models with growth projections`,`Generating an executive report and presentation`,`Strategic playbook on positioning, pricing, and GTM`],generatingSteps:[`Analyzing {url} to scope the market and identify key dimensions`,`Designing an agent to research competitors, trends, and market sizing`,`Configuring TAM/SAM/SOM models and growth projection pipelines`,`Setting up report generation for executive deck and GTM playbook`],featureSectionTitle:`From question to strategy`,featureCardTitles:[`Connects to your tools for context`,`Deliverables ready to present`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Computer plugs into Notion, Google Drive, Slack, and more — so it understands your priorities, internal data, and what matters most to you.`,`Market sizing models. Competitive maps. Executive decks. Computer delivers a full report package your team can use immediately.`],capabilitySectionTitle:`Your market intelligence team`,capabilitySectionSubtitle:`Name an industry, get back a complete market analysis.`,capabilityCards:[{title:`Deep Market Research`,description:`Computer scans hundreds of sources — industry reports, news, databases, and filings — to map the full competitive landscape.`},{title:`TAM/SAM/SOM Modeling`,description:`Computer builds market sizing models with growth projections, unit economics, and segment breakdowns — backed by real data.`},{title:`Executive Reports`,description:`Computer generates polished reports and presentations with market analysis, competitive positioning, and strategic recommendations.`},{title:`Competitive Mapping`,description:`Computer identifies key players, compares their positioning, pricing, and strengths — and shows exactly where the opportunities are.`},{title:`Go-to-Market Playbook`,description:`Computer creates a strategic playbook covering positioning, pricing, channels, and launch tactics — tailored to the market you're entering.`},{title:`Trend Monitoring`,description:`Computer tracks market shifts, new entrants, and regulatory changes — and alerts you when something moves.`}]});export{t as default};
